from test_helpers import test,solo
from test_manual_thanks_12612 import manual
grp=solo+"BuffTap.db.helperThanksOutsiders=true; IsInGroup=function() return true end; BuffTap:HelperEvent('GROUP_ROSTER_UPDATE'); BuffTap:ObserveSoloThanks(true); "
test('Outsider switch is off by default and grouped thanks stay blocked',solo+"assert(BuffTap.db.helperThanksOutsiders==false); IsInGroup=function() return true end; received(1459,'target'); assert(#emotes==0 and BuffTap:SoloThanksBlockReason()=='solo outdoor play required')")
test('Grouped outdoors with the switch on, an outsider is thanked',grp+"assert(BuffTap:SoloThanksBlockReason()==nil); received(1459,'target'); assert(#emotes==1 and emotes[1][2]=='target')")
test('A party member is never thanked',grp+"received(1459,'party1'); assert(#emotes==0 and BuffTap.helperThankStatus:find('in your group',1,true))")
test('A raid member is never thanked',grp+"IsInRaid=function() return true end; local oldE,oldG=UnitExists,UnitGUID; UnitExists=function(u) return u=='raid3' or oldE(u) end; UnitGUID=function(u) if u=='raid3' then return 'Player-RaidThree' end return oldG(u) end; UnitName=function(u) if u=='raid3' then return 'Third' end return 'Other' end; BuffTap:HelperEvent('GROUP_ROSTER_UPDATE'); BuffTap:ObserveSoloThanks(true); received(1459,'raid3'); assert(#emotes==0)")
test('Instances stay blocked with the switch on',grp+"IsInInstance=function() return true end; received(1459,'target'); assert(#emotes==0 and BuffTap:SoloThanksBlockReason()=='solo outdoor play required')")
test('Combat stays blocked with the switch on',grp+"combat=true; received(1459,'target'); assert(#emotes==0)")
test('Ignored outsiders are still skipped in a group',grp+"C_FriendList={IsIgnored=function() return true end,IsIgnoredByGuid=function() return true end}; received(1459,'target'); assert(#emotes==0)")
test('Unreadable roster thanks nobody',grp+"local oldG=UnitGUID; UnitGUID=function(u) if u=='party1' then return {secret=true} end return oldG(u) end; received(1459,'target'); assert(#emotes==0)")
test('Unknown group state with the switch on thanks nobody',grp+"IsInGroup=function() return nil end; IsInRaid=function() return nil end; received(1459,'target'); assert(#emotes==0)")
test('Turning the switch off blocks grouped thanks again',grp+"received(1459,'target'); assert(#emotes==1); BuffTap.db.helperThanksOutsiders=false; now=now+65; received(1243,'target'); assert(#emotes==1)")
test('Solo play is unchanged with the switch on',solo+"BuffTap.db.helperThanksOutsiders=true; received(1459,'target'); assert(#emotes==1)")
test('Joining a group clears the baseline so held buffs are not thanked',solo+"BuffTap.db.helperThanksOutsiders=true; received(1459,'target'); assert(#emotes==1); now=now+65; IsInGroup=function() return true end; BuffTap:HelperEvent('GROUP_ROSTER_UPDATE'); assert(not BuffTap.helperThankSeen); BuffTap:ObserveSoloThanks(true); BuffTap:ObserveSoloThanks(); assert(#emotes==1)")
test('A caster who joins the group before dispatch is not thanked',grp+"BuffTap.db.helperThankDelay=1; received(1459,'target'); assert(#emotes==0); local oldG=UnitGUID; local joined=oldG('target'); local oldE=UnitExists; UnitGUID=function(u) if u=='party1' then return joined end return oldG(u) end; advance(4); assert(#emotes==0)")
test('ThanksInGroup answers false when solo and nil when unreadable',solo+"assert(BuffTap:ThanksInGroup('Player-X')==false); IsInGroup=function() return true end; assert(BuffTap:ThanksInGroup(nil)==nil and BuffTap:ThanksInGroup('Player-X')==false); IsInGroup=function() return nil end; IsInRaid=function() return nil end; assert(BuffTap:ThanksInGroup('Player-X')==nil)")
test('Manual thank-you is not offered for a group member',grp+"BuffTap.db.manualThanks=true; UnitNameFromGUID=function() return 'Third','Member' end; local g=UnitGUID('party1'); BuffTap:OfferManualThanks({casterGUID=g,spellId=1459,name='External buff'}); assert(not (BuffTap.manualThanksQueue and BuffTap.manualThanksQueue[g]))")
test('Manual thank-you is dropped if the caster joins the group before it is sent',manual+"B:OfferManualThanks(a); local e=B.manualThanksQueue[a.casterGUID]; assert(e,'offer queued'); B.ThanksInGroup=function() return true end; assert(not B:SendManualThanks(e) and #sent==0 and not B.manualThanksQueue[a.casterGUID])")
test('Outsider switch follows the first switch and saves its choice',"local B=BuffTap; B:Options(); local h=B.helperWindow; assert(h.thanksOutsiders); B.db.helperThanks=false; B:Options(); assert(not h.thanksOutsiders:IsEnabled()); B.db.helperThanks=true; B:Options(); assert(h.thanksOutsiders:IsEnabled()); h.thanksOutsiders:SetChecked(true); h.thanksOutsiders.scripts.OnClick(h.thanksOutsiders); assert(B.db.helperThanksOutsiders==true); h.thanksOutsiders:SetChecked(false); h.thanksOutsiders.scripts.OnClick(h.thanksOutsiders); assert(B.db.helperThanksOutsiders==false)")
for loc in ['deDE','esES','frFR','ptBR']:
 from test_bufftap import ROOT
 txt=open(str(ROOT/('addon/BuffTap/Locales/'+loc+'.lua')),encoding='utf-8').read()
 for key in ['Thank players outside my group','In a party or raid outdoors, thank buffs from players who are not in your group. Group members are never thanked. Needs the first switch. Never in instances or combat.','Thanks identified buff providers while you play solo. Never in instances or combat. Emotes are spaced one second apart, with a one-minute cooldown per player.']:
  assert 'B.Locales.'+loc+'["'+key+'"]=' in txt,(loc,key)
from test_bufftap import ROOT as _ROOT
_RECORD=(_ROOT/'tests/nearby_preview_record.lua').read_text(encoding='utf-8-sig')
test('Thanks card rows keep the approved spacing and stay inside the card',_RECORD+"local B=BuffTap; B:Options(); local h=B.helperWindow; local function y(o) return o.__draw.points[1][3] end; assert(y(h.checks.helperThanks)==-138 and y(h.thanksOutsiders)==-166 and y(h.thanksResting)==-194 and y(h.manualThanks)==-222); assert(y(h.thankMessage)==-268 and y(h.thankMessageReset)==-266); assert(y(h.thanksCard)==-74 and h.thanksCard.__draw.h==226 and -y(h.thankMessage)+24<=74+226)")
